example:
// bynk.toml
[deploy.workers.live]
contexts = ["live.chat", "live.scores"]

// live/chat.bynk
service chat from websocket(in: Frame, out: Frame) { … }

// live/scores.bynk
context live.scores   // ✗ the second member of `live` with a WebSocket service
service scores from websocket(in: Frame, out: Frame) { … }

// bynk.toml
contexts = ["live.chat"]   // ✓ `live.scores` is a Worker of its own
